// Embedded copy of Images/mace.glb so the model still loads when index.html is opened
// straight from disk (file://), where browsers block fetching the .glb file.
// Regenerate this file if mace.glb is re-exported.
window.EMBEDDED_MODELS = window.EMBEDDED_MODELS || {};
window.EMBEDDED_MODELS["Images/mace.glb"] = "data:model/gltf-binary;base64,";
